```go
// ListRollouts returns every rollout matching the identity scope ordered by version ascending.
func (s *Store) ListRollouts(ctx context.Context, environment, namespace, configName string) ([]Rollout, error) {
	rows, err := s.db.QueryContext(ctx, `
		SELECT version, digest, revoked FROM config_rollouts
		WHERE target_environment = ? AND namespace = ? AND config_name = ?
		ORDER BY version ASC`, environment, namespace, configName)
	if err != nil {
		return nil, fmt.Errorf("list rollouts: %w", err)
	}
	defer rows.Close()

	var rollouts []Rollout
	for rows.Next() {
		rollout := Rollout{ConfigName: configName, TargetEnvironment: environment, Namespace: namespace}
		var revoked int
		if err := rows.Scan(&rollout.Version, &rollout.Digest, &revoked); err != nil {
			return nil, fmt.Errorf("scan rollout: %w", err)
		}
		rollout.Revoked = revoked != 0
		rollouts = append(rollouts, rollout)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list rollouts rows: %w", err)
	}
	for i := range rollouts {
		entries, err := readEntries(ctx, s.db, configName, environment, namespace, rollouts[i].Version)
		if err != nil {
			return nil, err
		}
		rollouts[i].Entries = entries
	}
	return rollouts, nil
}
