// dsn wires per-connection pragmas into the data source name so every pooled
// connection waits on contended writes instead of failing with SQLITE_BUSY.
func dsn(path string) string {
	separator := "?"
	if strings.Contains(path, "?") {
		separator = "&"
	}
	return path + separator + "_pragma=busy_timeout(5000)&_txlock=immediate"
}
