```go
package store

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
	"sort"
)

// Entry is a single key/value pair in a rollout.
type Entry struct {
	Key   string `json:"key"`
	Value string `json:"value"`
}

// Rollout is one registered config rollout record.
type Rollout struct {
	ConfigName        string  `json:"configName"`
	TargetEnvironment string  `json:"targetEnvironment"`
	Namespace         string  `json:"namespace"`
	Version           int64   `json:"version"`
	Entries           []Entry `json:"entries"`
	Digest            string  `json:"digest"`
	Revoked           bool    `json:"revoked"`
}

// ErrConflict reports that the rollout identity already exists with different content.
var ErrConflict = errors.New("config rollout identity exists with different content")

// DigestEntries returns the canonical content digest for a set of entries.
func DigestEntries(entries []Entry) string {
	ordered := SortedEntries(entries)
	sum := sha256.New()
	for _, entry := range ordered {
		fmt.Fprintf(sum, "%d:%s%d:%s", len(entry.Key), entry.Key, len(entry.Value), entry.Value)
	}
	return hex.EncodeToString(sum.Sum(nil))
}

// SortedEntries returns entries ordered by key without mutating the input.
func SortedEntries(entries []Entry) []Entry {
	ordered := make([]Entry, len(entries))
	copy(ordered, entries)
	sort.Slice(ordered, func(i, j int) bool { return ordered[i].Key < ordered[j].Key })
	return ordered
}
```

CreateRollout:

```go
// CreateRollout stores a new rollout in a single transaction. It returns the stored
// record and whether it was newly created. Submitting identical content for an existing
// identity returns the stored record with created=false; different content for an
// existing identity returns ErrConflict.
func (s *Store) CreateRollout(ctx context.Context, rollout Rollout) (Rollout, bool, error) {
	rollout.Entries = SortedEntries(rollout.Entries)
	rollout.Digest = DigestEntries(rollout.Entries)
	rollout.Revoked = false

	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return Rollout{}, false, fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback()

	result, err := tx.ExecContext(ctx, `
		INSERT INTO config_rollouts (config_name, target_environment, namespace, version, digest, revoked)
		VALUES (?, ?, ?, ?, ?, 0)
		ON CONFLICT DO NOTHING`,
		rollout.ConfigName, rollout.TargetEnvironment, rollout.Namespace, rollout.Version, rollout.Digest)
	if err != nil {
		return Rollout{}, false, fmt.Errorf("insert rollout: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return Rollout{}, false, fmt.Errorf("insert rollout rows: %w", err)
	}
	if affected == 0 {
		stored, err := readRollout(ctx, tx, rollout.ConfigName, rollout.TargetEnvironment, rollout.Namespace, rollout.Version)
		if err != nil {
			return Rollout{}, false, err
		}
		if stored.Digest != rollout.Digest {
			return Rollout{}, false, ErrConflict
		}
		return stored, false, nil
	}

	for _, entry := range rollout.Entries {
		if _, err := tx.ExecContext(ctx, `
			INSERT INTO config_rollout_entries (config_name, target_environment, namespace, version, entry_key, entry_value)
			VALUES (?, ?, ?, ?, ?, ?)`,
			rollout.ConfigName, rollout.TargetEnvironment, rollout.Namespace, rollout.Version, entry.Key, entry.Value); err != nil {
			return Rollout{}, false, fmt.Errorf("insert entry: %w", err)
		}
	}
	if err := tx.Commit(); err != nil {
		return Rollout{}, false, fmt.Errorf("commit: %w", err)
	}
	return rollout, true, nil
}
```

Note: on the conflict path we `return stored, false, nil` without committing — the deferred `tx.Rollback()` cleans up. Read-only tx rollback is fine.

